import java.nio.file.*;import java.util.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class OtherHousingCommandsPatch {
 static MethodNode copy(MethodNode m){var n=new MethodNode(m.access,m.name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(n);return n;}
 static String norm(MethodNode m){return OpeningDelta.norm(m).replaceAll("lambda\\$([A-Za-z0-9_$]+)\\$[0-9]+", "lambda\\$$1\\$N");}
 static MethodNode get(ClassNode c,String n){return c.methods.stream().filter(x->x.name.equals(n)).findFirst().orElseThrow();}
 static boolean branch(AbstractInsnNode n){return n instanceof MethodInsnNode x&&x.owner.endsWith("/ChacaLink")&&x.name.equals("branch");}
 static List<AbstractInsnNode> real(MethodNode m){var r=new ArrayList<AbstractInsnNode>();for(var n:m.instructions)if(n.getOpcode()>=0)r.add(n);return r;}
 static void rename(MethodNode m,String owner,Map<String,String> map){if(map.containsKey(m.name))m.name=map.get(m.name);for(var n:m.instructions)if(n instanceof InvokeDynamicInsnNode v)for(int i=0;i<v.bsmArgs.length;i++)if(v.bsmArgs[i] instanceof Handle h&&h.getOwner().equals(owner)&&map.containsKey(h.getName()))v.bsmArgs[i]=new Handle(h.getTag(),h.getOwner(),map.get(h.getName()),h.getDesc(),h.isInterface());}
 public static void main(String[]a)throws Exception{
 var live=OpeningDelta.read(Files.readAllBytes(Path.of(a[0])),0);var fresh=OpeningDelta.read(Files.readAllBytes(Path.of(a[1])),0);var old=OpeningDelta.read(Files.readAllBytes(Path.of(a[2])),0);var src=copy(get(fresh,"register"));var nodes=real(src);int mark=-1,start=-1,stop=-1;
 for(int i=0;i<nodes.size();i++)if(nodes.get(i) instanceof LdcInsnNode l&&l.cst.equals("\uBC29\uBB38\uC21C\uC704")){mark=i;break;}if(mark<0)throw new IllegalStateException("ranking literal absent");for(int i=mark-1;i>=0;i--)if(branch(nodes.get(i))){start=i+1;break;}for(int i=mark+1;i<nodes.size();i++)if(branch(nodes.get(i))){stop=i+1;break;}if(start<0||stop<0)throw new IllegalStateException("ranking statement boundary");var addition=new ArrayList<>(nodes.subList(start,stop));for(var n:addition)src.instructions.remove(n);if(!norm(src).equals(norm(get(old,"register"))))throw new IllegalStateException("register source delta exceeds ranking");
 for(var m:fresh.methods)if(!m.name.startsWith("lambda$")&&!m.name.equals("register")&&!m.name.equals("visitRanking")){var was=old.methods.stream().filter(x->OpeningDelta.key(x).equals(OpeningDelta.key(m))).findFirst().orElseThrow();if(!norm(m).equals(norm(was)))throw new IllegalStateException("other source method changed "+OpeningDelta.key(m));}
 if(live.methods.stream().anyMatch(x->x.name.equals("visitRanking")))throw new IllegalStateException("existing ranking collision");var map=new HashMap<String,String>();for(var n:addition)if(n instanceof InvokeDynamicInsnNode v)for(Object b:v.bsmArgs)if(b instanceof Handle h&&h.getOwner().equals(live.name))map.put(h.getName(),"opening$ranking$"+map.size());var visit=copy(get(fresh,"visitRanking"));for(var n:visit.instructions)if(n instanceof InvokeDynamicInsnNode v)for(Object b:v.bsmArgs)if(b instanceof Handle h&&h.getOwner().equals(live.name))map.put(h.getName(),"opening$ranking$"+map.size());
 var before=new HashMap<String,String>();for(var m:live.methods)before.put(OpeningDelta.key(m),OpeningDelta.norm(m));rename(visit,live.name,map);live.methods.add(visit);for(var item:map.entrySet()){if(live.methods.stream().anyMatch(x->x.name.equals(item.getValue())))throw new IllegalStateException("fresh helper collision");var m=copy(get(fresh,item.getKey()));rename(m,live.name,map);live.methods.add(m);}
 var list=new InsnList();var labels=new HashMap<LabelNode,LabelNode>();for(var n:addition)list.add(n.clone(labels));var wrap=new MethodNode();wrap.instructions=list;rename(wrap,live.name,map);var target=get(live,"register");AbstractInsnNode at=null;boolean seen=false;for(var n:target.instructions){if(n instanceof LdcInsnNode l&&l.cst.equals("\uAC00\uAD6C\uBAA9\uB85D"))seen=true;if(seen&&branch(n)){at=n;break;}}if(at==null)throw new IllegalStateException("live furniture-list anchor absent");var added=new ArrayList<AbstractInsnNode>();for(var n:list)added.add(n);target.instructions.insert(at,list);var patched=copy(target);for(var n:added)target.instructions.remove(n);if(!OpeningDelta.norm(target).equals(before.get(OpeningDelta.key(target))))throw new IllegalStateException("register strip mismatch");live.methods.remove(target);live.methods.add(patched);
 for(var m:live.methods)if(before.containsKey(OpeningDelta.key(m))&&!m.name.equals("register")&&!OpeningDelta.norm(m).equals(before.get(OpeningDelta.key(m))))throw new IllegalStateException("unrelated live method changed");var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);live.accept(w);byte[] bytes=w.toByteArray();var c=OpeningDelta.read(bytes,0);for(var m:c.methods)if((m.access&1280)==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);Files.write(Path.of(a[3]),bytes);System.out.println("PASS HOUSING_COMMANDS sourceDeltaOnlyRanking=true insertedStripRestoresLive=true unrelatedMethodsPreserved="+(before.size()-1)+" uniqueHelpers="+map.size()+" newCommands=1");
 }
}
